/** 🧱️ Shared exact-word corpus and independent SQLite relational queries. */
import {expect,test} from "bun:test";
import {Database} from "bun:sqlite";
import Ajv from "ajv";
import createTileSchema from "../../../🧬️mutations/🧱️create-tile/🧬️schema/🔣️.json";
import changeMediaSchema from "../../../🧬️mutations/🖼️change-tile-media/🧬️schema/🔣️.json";
import f from "../../🧫️fixtures/🪶️sqlite/🔣️.json";
import type {Grid3dSnapshot} from "../../🟦️.ts";
import {WFC_GRID3D_SQLITE_SCHEMA,grid3dSnapshotToSqliteDatabase,grid3dSnapshotFromSqliteDatabase} from "../../🪶️sqlite/🟦️.ts";
import {exportSqliteDatabase,importSqliteDatabase} from "@semio-tech/framework";
const bits=(word:string)=>({bits:BigInt("0x"+word)});
test("grid3d mutation media payloads are independently self-contained draft07 documents",()=>{
 const ajv=new Ajv({strict:true}).addKeyword("x-semio-ui"),create=ajv.compile(createTileSchema),change=ajv.compile(changeMediaSchema);
 for(const media of f.payloadMedia){expect(create({tile:{id:"",weight:1,media}})).toBe(true);expect(change({tileId:"",media})).toBe(true);}
 const media={kind:"mesh",mesh:{positions:[0],indices:[4294967296]}};expect(create({tile:{id:"",weight:1,media}})).toBe(false);expect(change({tileId:"",media})).toBe(false);
});
const input:Grid3dSnapshot={schema:f.schema,seed:BigInt(f.seed),width:f.width,height:f.height,depth:f.depth,periodicX:f.periodicX,periodicY:f.periodicY,periodicZ:f.periodicZ,cellSizesX:f.cellSizesXBits.map(bits),cellSizesY:f.cellSizesYBits.map(bits),cellSizesZ:f.cellSizesZBits.map(bits),tiles:[{id:"mesh 🧬",label:"",weight:bits("3ff0000000000000"),media:{kind:"mesh",mesh:{positions:["8000000000000000","7ff8000000004321","0000000000000001","3ff0000000000000"].map(bits),indices:[4294967295,0],color:{r:4294967295,g:2,b:3,a:4}}}},{id:"child",weight:bits("7ff0000000000001"),media:{kind:"meshChild",child:{childId:"owned-child",target:{artifactId:"semio-mesh",dialect:{artifactKind:"s.stdio.semio",standard:"v1",subset:"mesh"}}}}}],rules:[{id:"permission",tileAId:"mesh 🧬",tileBId:"child",direction:"FRONT",allowed:false}],pinned:f.pinned,masked:f.masked};
test("grid3d exact native IEEE words and independent graph edit",async()=>{expect(WFC_GRID3D_SQLITE_SCHEMA).toBe(await Bun.file(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url)).text());const database=await grid3dSnapshotToSqliteDatabase(input);const db=Database.deserialize(await exportSqliteDatabase(database));try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query("SELECT a.authored_id AS a,b.authored_id AS b,direction FROM wfc_grid3d_rule JOIN wfc_grid3d_tile a ON tile_a_id=a.authored_id JOIN wfc_grid3d_tile b ON tile_b_id=b.authored_id").get()).toEqual({a:"mesh 🧬",b:"child",direction:"FRONT"});expect(await grid3dSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input);db.query("UPDATE wfc_grid3d_color SET red=7").run();const expected=structuredClone(input);if(expected.tiles[0]!.media.kind!=="mesh")throw Error("fixture media");expected.tiles[0]!.media.mesh.color!.r=7;expect(await grid3dSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(expected);}finally{db.close();}});
test("grid3d malformed graph/IEEE/scalar widths and controlled allocation",async()=>{const original=await grid3dSnapshotToSqliteDatabase(input);for(const edit of [(d:any)=>d.tables[8].rows[0].values[4]=999n,(d:any)=>d.tables[4].rows[0].values[2]=99n,(d:any)=>d.tables[2].rows[0].values[6]="unknown",(d:any)=>d.tables[6].rows[0].values[1]=-1n,(d:any)=>d.tables[1].rows[0].values[5]=1n]){const d=structuredClone(original);edit(d);await expect(grid3dSnapshotFromSqliteDatabase(d)).rejects.toThrow();}await expect(grid3dSnapshotToSqliteDatabase(input,{maxRows:1})).rejects.toThrow();await expect(grid3dSnapshotFromSqliteDatabase(original,{maxValueBytes:1})).rejects.toThrow();const c=new AbortController();c.abort();await expect(grid3dSnapshotToSqliteDatabase(input,{signal:c.signal})).rejects.toThrow();const empty={...input,tiles:[],rules:[],pinned:[],masked:[],cellSizesX:[],cellSizesY:[],cellSizesZ:[]};expect(await grid3dSnapshotFromSqliteDatabase(await grid3dSnapshotToSqliteDatabase(empty))).toEqual(empty);});

test("grid3d authored duplicate and unresolved identifiers remain literal owned state",async()=>{for(const fixture of f.literalIdentityStates){const source=structuredClone(input);source.tiles.forEach((tile,index)=>{tile.id=fixture.tileIds[index]!;});source.rules[0]!.id=fixture.ruleId;source.rules[0]!.tileAId=fixture.tileAId;source.rules[0]!.tileBId=fixture.tileBId;source.rules.push(structuredClone(source.rules[0]!));source.pinned[0]!.tileId=fixture.pinTileId;const db=Database.deserialize(await exportSqliteDatabase(await grid3dSnapshotToSqliteDatabase(source)));try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query("SELECT authored_id FROM wfc_grid3d_tile ORDER BY ordinal").all()).toEqual(fixture.tileIds.map(authored_id=>({authored_id})));expect(db.query("SELECT authored_id,tile_a_id,tile_b_id FROM wfc_grid3d_rule ORDER BY ordinal").all()).toEqual([0,1].map(()=>({authored_id:fixture.ruleId,tile_a_id:fixture.tileAId,tile_b_id:fixture.tileBId})));expect(await grid3dSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(source);}finally{db.close();}}});

