import Ajv2020 from "ajv/dist/2020";
import semanticPlan from "../../🧫️fixtures/🪶️sqlite/🛂️semantic/🔣️.json";
import semanticSchema from "../../🧫️fixtures/🪶️sqlite/🛂️semantic/🧬️schema/🔣️.json";
test("grid3d independently measures every authored semantic cell and IEEE companion",async()=>{
 const validate=new Ajv2020({strict:true}).compile(semanticSchema);expect(validate(semanticPlan)).toBe(true);expect(validate({...semanticPlan,unknown:true})).toBe(false);
 const database=await grid3dSnapshotToSqliteDatabase(input),db=Database.deserialize(await exportSqliteDatabase(database));let rows=0,bytes=0,columns=0;
 try{for(const[table,count]of Object.entries(semanticPlan.tableRows)){const fields=(db.query("PRAGMA table_info("+table+")").all()as{name:string}[]).map(v=>v.name);columns=Math.max(columns,fields.length);const quote=(v:string)=>'"'+v.replaceAll('"','""')+'"';const expression=fields.map(v=>{const x=quote(v);return "CASE typeof("+x+") WHEN 'integer' THEN 8 WHEN 'real' THEN 8 WHEN 'text' THEN length(CAST("+x+" AS BLOB)) WHEN 'blob' THEN length("+x+") ELSE 0 END";}).join("+");const actual=db.query("SELECT COUNT(*) AS rows,COALESCE(SUM("+expression+"),0) AS bytes FROM "+table).get()as{rows:number;bytes:number};expect(actual.rows).toBe(count);rows+=actual.rows;bytes+=actual.bytes;}expect({rows,bytes,columns}).toEqual({rows:semanticPlan.rows,bytes:semanticPlan.valueBytes,columns:semanticPlan.columns});}finally{db.close();}
});
